from pathlib import Path

ROOT = Path.cwd()
path = ROOT / "app/(portal)/crafting/crafting-workbench.tsx"

if not path.exists():
    raise SystemExit(f"ERROR: Missing expected file: {path}")

content = '"use client";\n\nimport {\n  useMemo,\n  useState,\n  useTransition,\n} from "react";\nimport { useRouter } from "next/navigation";\n\nimport { craftRecipeAction } from "./actions";\n\nexport type CraftingInventoryItem = {\n  id: string;\n  name: string;\n  slug: string;\n  description: string;\n  image_url: string | null;\n  quality: string;\n  quantity: number;\n};\n\nexport type CraftingIngredient = {\n  item_id: string;\n  name: string;\n  slug: string;\n  description: string;\n  image_url: string | null;\n  quality: string;\n  quantity: number;\n  sort_order: number;\n};\n\nexport type KnownCraftingRecipe = {\n  id: string;\n  name: string;\n  slug: string;\n  description: string;\n  result_quantity: number;\n  sort_order: number;\n  result: {\n    id: string;\n    name: string;\n    slug: string;\n    description: string;\n    image_url: string | null;\n    quality: string;\n  };\n  ingredients: CraftingIngredient[];\n};\n\ntype CraftingWorkbenchProps = {\n  recipes: KnownCraftingRecipe[];\n  inventory: CraftingInventoryItem[];\n};\n\ntype Notice = {\n  tone: "success" | "error";\n  text: string;\n};\n\nfunction qualityLabel(value: string) {\n  if (!value) return "Average";\n\n  return value\n    .split(/[-_\\s]+/)\n    .filter(Boolean)\n    .map(\n      (part) =>\n        part.charAt(0).toUpperCase() +\n        part.slice(1),\n    )\n    .join(" ");\n}\n\nfunction ItemImage({\n  src,\n  fallback = "◇",\n  size = "md",\n}: {\n  src: string | null;\n  fallback?: string;\n  size?: "sm" | "md" | "lg";\n}) {\n  const dimensions =\n    size === "lg"\n      ? "h-20 w-20"\n      : size === "sm"\n        ? "h-10 w-10"\n        : "h-12 w-12";\n\n  return (\n    <div\n      className={`flex ${dimensions} shrink-0 items-center justify-center overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-0d0a08))]`}\n    >\n      {src ? (\n        // eslint-disable-next-line @next/next/no-img-element\n        <img\n          src={src}\n          alt=""\n          className="h-full w-full object-contain p-1"\n        />\n      ) : (\n        <span className="font-serif text-xl text-[rgb(var(--sep-colour-756247))]">\n          {fallback}\n        </span>\n      )}\n    </div>\n  );\n}\n\nfunction ingredientPosition(\n  index: number,\n  total: number,\n) {\n  if (total === 1) {\n    return "col-start-2 row-start-2";\n  }\n\n  if (total === 2) {\n    return index === 0\n      ? "col-start-1 row-start-2"\n      : "col-start-3 row-start-2";\n  }\n\n  if (total === 3) {\n    return [\n      "col-start-2 row-start-1",\n      "col-start-1 row-start-3",\n      "col-start-3 row-start-3",\n    ][index] ?? "";\n  }\n\n  if (total === 4) {\n    return [\n      "col-start-2 row-start-1",\n      "col-start-3 row-start-2",\n      "col-start-2 row-start-3",\n      "col-start-1 row-start-2",\n    ][index] ?? "";\n  }\n\n  return "";\n}\n\nexport function CraftingWorkbench({\n  recipes,\n  inventory,\n}: CraftingWorkbenchProps) {\n  const router = useRouter();\n\n  const [isPending, startTransition] =\n    useTransition();\n\n  const [\n    selectedRecipeId,\n    setSelectedRecipeId,\n  ] = useState(\n    recipes[0]?.id ?? "",\n  );\n\n  const [\n    filledSlots,\n    setFilledSlots,\n  ] = useState<\n    Record<string, boolean>\n  >({});\n\n  const [\n    notice,\n    setNotice,\n  ] = useState<Notice | null>(\n    null,\n  );\n\n  const [\n    draggedItemId,\n    setDraggedItemId,\n  ] = useState<string | null>(\n    null,\n  );\n\n  const selectedRecipe =\n    useMemo(\n      () =>\n        recipes.find(\n          (recipe) =>\n            recipe.id ===\n            selectedRecipeId,\n        ) ?? null,\n      [\n        recipes,\n        selectedRecipeId,\n      ],\n    );\n\n  const inventoryByItemId =\n    useMemo(\n      () =>\n        new Map(\n          inventory.map(\n            (item) =>\n              [\n                item.id,\n                item,\n              ] as const,\n          ),\n        ),\n      [inventory],\n    );\n\n  function chooseRecipe(\n    recipeId: string,\n  ) {\n    setSelectedRecipeId(\n      recipeId,\n    );\n    setFilledSlots({});\n    setNotice(null);\n  }\n\n  function fillIngredient(\n    itemId: string,\n  ) {\n    if (!selectedRecipe) {\n      return;\n    }\n\n    const requirement =\n      selectedRecipe.ingredients.find(\n        (ingredient) =>\n          ingredient.item_id ===\n          itemId,\n      );\n\n    if (!requirement) {\n      setNotice({\n        tone: "error",\n        text:\n          "That ingredient is not used by this recipe.",\n      });\n      return;\n    }\n\n    const owned =\n      inventoryByItemId.get(\n        itemId,\n      )?.quantity ?? 0;\n\n    if (\n      owned <\n      requirement.quantity\n    ) {\n      setNotice({\n        tone: "error",\n        text: `You need ${requirement.quantity} × ${requirement.name}, but only have ${owned}.`,\n      });\n      return;\n    }\n\n    setFilledSlots(\n      (current) => ({\n        ...current,\n        [itemId]: true,\n      }),\n    );\n\n    setNotice(null);\n  }\n\n  function autofill() {\n    if (!selectedRecipe) {\n      return;\n    }\n\n    const next: Record<\n      string,\n      boolean\n    > = {};\n\n    for (\n      const ingredient of\n      selectedRecipe.ingredients\n    ) {\n      const owned =\n        inventoryByItemId.get(\n          ingredient.item_id,\n        )?.quantity ?? 0;\n\n      if (\n        owned >=\n        ingredient.quantity\n      ) {\n        next[\n          ingredient.item_id\n        ] = true;\n      }\n    }\n\n    setFilledSlots(next);\n    setNotice(null);\n  }\n\n  const allRequirementsOwned =\n    selectedRecipe?.ingredients.every(\n      (ingredient) => {\n        const owned =\n          inventoryByItemId.get(\n            ingredient.item_id,\n          )?.quantity ?? 0;\n\n        return (\n          owned >=\n          ingredient.quantity\n        );\n      },\n    ) ?? false;\n\n  const allSlotsFilled =\n    selectedRecipe?.ingredients.every(\n      (ingredient) =>\n        filledSlots[\n          ingredient.item_id\n        ] === true,\n    ) ?? false;\n\n  function craft() {\n    if (\n      !selectedRecipe ||\n      !allRequirementsOwned ||\n      !allSlotsFilled ||\n      isPending\n    ) {\n      return;\n    }\n\n    setNotice(null);\n\n    startTransition(\n      async () => {\n        const result =\n          await craftRecipeAction(\n            selectedRecipe.id,\n          );\n\n        setNotice({\n          tone: result.success\n            ? "success"\n            : "error",\n          text: result.message,\n        });\n\n        if (result.success) {\n          setFilledSlots({});\n          router.refresh();\n        }\n      },\n    );\n  }\n\n  if (!recipes.length) {\n    return (\n      <section className="border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]/95 p-10 text-center">\n        <p className="text-[9px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-886c48))]">\n          Recipe Book\n        </p>\n\n        <h2 className="mt-3 font-serif text-2xl text-[rgb(var(--sep-colour-ead6ad))]">\n          No recipes known\n        </h2>\n\n        <p className="mx-auto mt-3 max-w-xl text-[11px] leading-6 text-[rgb(var(--sep-colour-9f9281))]">\n          This character has not learned any crafting recipes yet.\n        </p>\n      </section>\n    );\n  }\n\n  const spatialLayout =\n    (selectedRecipe?.ingredients.length ?? 0) <= 4;\n\n  return (\n    <div className="grid min-h-[620px] w-full gap-4 xl:grid-cols-[1fr_1fr_2fr]">\n      <section className="flex min-h-0 flex-col border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]/95">\n        <div className="shrink-0 border-b border-[rgb(var(--sep-colour-60482e))]/35 px-4 py-3">\n          <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-886c48))]">\n            Learned Knowledge\n          </p>\n\n          <div className="mt-1 flex items-end justify-between gap-3">\n            <h2 className="font-serif text-xl text-[rgb(var(--sep-colour-ead6ad))]">\n              Known Recipes\n            </h2>\n\n            <span className="text-[7px] uppercase tracking-[0.15em] text-[rgb(var(--sep-colour-806b50))]">\n              {recipes.length}\n            </span>\n          </div>\n        </div>\n\n        <div className="min-h-0 flex-1 space-y-2 overflow-y-auto p-3">\n          {recipes.map(\n            (recipe) => {\n              const active =\n                recipe.id ===\n                selectedRecipeId;\n\n              const available =\n                recipe.ingredients.every(\n                  (ingredient) =>\n                    (inventoryByItemId.get(\n                      ingredient.item_id,\n                    )?.quantity ??\n                      0) >=\n                    ingredient.quantity,\n                );\n\n              return (\n                <button\n                  key={recipe.id}\n                  type="button"\n                  onClick={() =>\n                    chooseRecipe(\n                      recipe.id,\n                    )\n                  }\n                  className={`flex w-full items-center gap-3 border px-3 py-3 text-left transition ${\n                    active\n                      ? "border-[rgb(var(--sep-colour-a17a45))] bg-[rgb(var(--sep-colour-3b2919))]"\n                      : "border-[rgb(var(--sep-colour-60482e))]/50 bg-[rgb(var(--sep-colour-100c09))] hover:border-[rgb(var(--sep-colour-9a7344))]/80 hover:bg-[rgb(var(--sep-colour-271c12))]"\n                  }`}\n                >\n                  <ItemImage\n                    src={\n                      recipe.result\n                        .image_url\n                    }\n                    size="sm"\n                    fallback="✦"\n                  />\n\n                  <div className="min-w-0 flex-1">\n                    <p className="line-clamp-2 font-serif text-[14px] leading-4 text-[rgb(var(--sep-colour-ead6ad))]">\n                      {recipe.name}\n                    </p>\n\n                    <p\n                      className={`mt-1 text-[7px] uppercase tracking-[0.12em] ${\n                        available\n                          ? "text-[rgb(var(--sep-colour-b88d54))]"\n                          : "text-[rgb(var(--sep-colour-806b50))]"\n                      }`}\n                    >\n                      {available\n                        ? "Ready"\n                        : "Materials missing"}\n                    </p>\n                  </div>\n                </button>\n              );\n            },\n          )}\n        </div>\n      </section>\n\n      <section className="flex min-h-0 flex-col border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]/95">\n        <div className="shrink-0 border-b border-[rgb(var(--sep-colour-60482e))]/35 px-4 py-3">\n          <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-886c48))]">\n            Materials at Hand\n          </p>\n\n          <h2 className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-ead6ad))]">\n            Ingredients\n          </h2>\n\n          <p className="mt-1 text-[7px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-806b50))]">\n            Drag or double-click to place\n          </p>\n        </div>\n\n        <div className="min-h-0 flex-1 space-y-2 overflow-y-auto p-3">\n          {inventory.length ? (\n            inventory.map(\n              (item) => {\n                const usedByRecipe =\n                  selectedRecipe?.ingredients.some(\n                    (ingredient) =>\n                      ingredient.item_id ===\n                      item.id,\n                  );\n\n                return (\n                  <button\n                    key={item.id}\n                    type="button"\n                    draggable\n                    onDragStart={(\n                      event,\n                    ) => {\n                      event.dataTransfer.setData(\n                        "text/plain",\n                        item.id,\n                      );\n\n                      event.dataTransfer.effectAllowed =\n                        "copy";\n\n                      setDraggedItemId(\n                        item.id,\n                      );\n                    }}\n                    onDragEnd={() =>\n                      setDraggedItemId(\n                        null,\n                      )\n                    }\n                    onDoubleClick={() =>\n                      fillIngredient(\n                        item.id,\n                      )\n                    }\n                    className={`flex w-full items-center gap-3 border px-3 py-2.5 text-left transition ${\n                      draggedItemId ===\n                      item.id\n                        ? "border-[rgb(var(--sep-colour-a17a45))] bg-[rgb(var(--sep-colour-3b2919))]"\n                        : usedByRecipe\n                          ? "border-[rgb(var(--sep-colour-765937))] bg-[rgb(var(--sep-colour-271c12))] hover:border-[rgb(var(--sep-colour-a17a45))] hover:bg-[rgb(var(--sep-colour-3b2919))]"\n                          : "border-[rgb(var(--sep-colour-60482e))]/50 bg-[rgb(var(--sep-colour-100c09))] opacity-70 hover:border-[rgb(var(--sep-colour-9a7344))]/80 hover:opacity-100"\n                    }`}\n                  >\n                    <ItemImage\n                      src={\n                        item.image_url\n                      }\n                    />\n\n                    <div className="min-w-0 flex-1">\n                      <p className="truncate text-[11px] text-[rgb(var(--sep-colour-d4bd94))]">\n                        {item.name}\n                      </p>\n\n                      <p className="mt-1 text-[7px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-806b50))]">\n                        {qualityLabel(\n                          item.quality,\n                        )}\n                      </p>\n                    </div>\n\n                    <span className="shrink-0 border border-[rgb(var(--sep-colour-60482e))]/45 bg-black/20 px-2 py-1 text-[10px] text-[rgb(var(--sep-colour-d4bd94))]">\n                      ×{item.quantity}\n                    </span>\n                  </button>\n                );\n              },\n            )\n          ) : (\n            <p className="px-2 py-4 text-[10px] leading-5 text-[rgb(var(--sep-colour-9f9281))]">\n              No crafting materials carried.\n            </p>\n          )}\n        </div>\n      </section>\n\n      <section className="flex min-h-0 flex-col border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]/95">\n        <div className="shrink-0 border-b border-[rgb(var(--sep-colour-60482e))]/35 px-5 py-4">\n          <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-886c48))]">\n            Crafting Bench\n          </p>\n\n          <h2 className="mt-1 font-serif text-2xl text-[rgb(var(--sep-colour-ead6ad))]">\n            {selectedRecipe?.name}\n          </h2>\n\n          <p className="mt-2 max-w-3xl text-[10px] leading-5 text-[rgb(var(--sep-colour-9f9281))]">\n            {selectedRecipe?.description}\n          </p>\n        </div>\n\n        <div className="flex min-h-0 flex-1 flex-col p-5">\n          <div className="flex min-h-[390px] flex-1 items-center justify-center border border-[rgb(var(--sep-colour-60482e))]/35 bg-black/10 p-5">\n            <div\n              className={\n                spatialLayout\n                  ? "grid h-full w-full max-w-[680px] grid-cols-3 grid-rows-3 items-center justify-items-center gap-4"\n                  : "grid w-full max-w-[720px] grid-cols-2 gap-4 2xl:grid-cols-3"\n              }\n            >\n              {selectedRecipe?.ingredients.map(\n                (\n                  ingredient,\n                  index,\n                ) => {\n                  const owned =\n                    inventoryByItemId.get(\n                      ingredient.item_id,\n                    )?.quantity ?? 0;\n\n                  const filled =\n                    filledSlots[\n                      ingredient.item_id\n                    ] === true;\n\n                  const enough =\n                    owned >=\n                    ingredient.quantity;\n\n                  const draggingMatch =\n                    draggedItemId ===\n                    ingredient.item_id;\n\n                  return (\n                    <div\n                      key={\n                        ingredient.item_id\n                      }\n                      onDragOver={(\n                        event,\n                      ) => {\n                        if (\n                          draggedItemId ===\n                          ingredient.item_id\n                        ) {\n                          event.preventDefault();\n                          event.dataTransfer.dropEffect =\n                            "copy";\n                        }\n                      }}\n                      onDrop={(\n                        event,\n                      ) => {\n                        event.preventDefault();\n\n                        const itemId =\n                          event.dataTransfer.getData(\n                            "text/plain",\n                          );\n\n                        fillIngredient(\n                          itemId,\n                        );\n\n                        setDraggedItemId(\n                          null,\n                        );\n                      }}\n                      className={`${spatialLayout ? ingredientPosition(index, selectedRecipe.ingredients.length) : ""} w-full max-w-[200px] border transition ${\n                        filled\n                          ? "border-[rgb(var(--sep-colour-a17a45))] bg-[rgb(var(--sep-colour-3b2919))]"\n                          : draggingMatch\n                            ? "border-[rgb(var(--sep-colour-9a7344))] bg-[rgb(var(--sep-colour-271c12))]"\n                            : "border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-100c09))]"\n                      }`}\n                    >\n                      <button\n                        type="button"\n                        onClick={() => {\n                          if (filled) {\n                            setFilledSlots(\n                              (\n                                current,\n                              ) => ({\n                                ...current,\n                                [ingredient.item_id]:\n                                  false,\n                              }),\n                            );\n                          } else {\n                            fillIngredient(\n                              ingredient.item_id,\n                            );\n                          }\n                        }}\n                        className="flex min-h-[104px] w-full flex-col items-center justify-center px-3 py-3 text-center"\n                      >\n                        <ItemImage\n                          src={\n                            ingredient.image_url\n                          }\n                        />\n\n                        <p className="mt-2 line-clamp-2 text-[10px] leading-4 text-[rgb(var(--sep-colour-d4bd94))]">\n                          {ingredient.name}\n                        </p>\n\n                        <p\n                          className={`mt-1 text-[8px] ${\n                            enough\n                              ? "text-[rgb(var(--sep-colour-b88d54))]"\n                              : "text-[rgb(var(--sep-colour-806b50))]"\n                          }`}\n                        >\n                          {owned} /{" "}\n                          {\n                            ingredient.quantity\n                          }\n                        </p>\n\n                        <p className="mt-1 text-[6px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-806b50))]">\n                          {filled\n                            ? "Placed"\n                            : enough\n                              ? "Drop here"\n                              : "Missing"}\n                        </p>\n                      </button>\n                    </div>\n                  );\n                },\n              )}\n            </div>\n          </div>\n\n          <div className="mt-4 grid gap-4 border border-[rgb(var(--sep-colour-60482e))]/45 bg-black/20 p-4 lg:grid-cols-[1fr_auto] lg:items-center">\n            <div className="flex items-center gap-4">\n              <ItemImage\n                src={\n                  selectedRecipe?.result\n                    .image_url ??\n                  null\n                }\n                size="lg"\n                fallback="✦"\n              />\n\n              <div className="min-w-0">\n                <p className="text-[8px] uppercase tracking-[0.22em] text-[rgb(var(--sep-colour-806b50))]">\n                  Result\n                </p>\n\n                <p className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d4bd94))]">\n                  {\n                    selectedRecipe?.result_quantity\n                  }{" "}\n                  ×{" "}\n                  {\n                    selectedRecipe?.result\n                      .name\n                  }\n                </p>\n\n                {notice ? (\n                  <p\n                    className={`mt-2 text-[9px] leading-4 ${\n                      notice.tone ===\n                      "success"\n                        ? "text-[rgb(var(--sep-colour-b88d54))]"\n                        : "text-[rgb(var(--sep-colour-c17b6c))]"\n                    }`}\n                  >\n                    {notice.text}\n                  </p>\n                ) : null}\n              </div>\n            </div>\n\n            <div className="grid grid-cols-2 gap-2">\n              <button\n                type="button"\n                onClick={autofill}\n                disabled={\n                  !allRequirementsOwned ||\n                  isPending\n                }\n                className="border border-[rgb(var(--sep-colour-765937))] bg-[rgb(var(--sep-colour-271c12))] px-4 py-3 text-[8px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-dfc79c))] transition hover:border-[rgb(var(--sep-colour-a17a45))] hover:bg-[rgb(var(--sep-colour-3b2919))] disabled:cursor-not-allowed disabled:opacity-35"\n              >\n                Fill Ingredients\n              </button>\n\n              <button\n                type="button"\n                onClick={craft}\n                disabled={\n                  !allRequirementsOwned ||\n                  !allSlotsFilled ||\n                  isPending\n                }\n                className="border border-[rgb(var(--sep-colour-765937))] bg-[rgb(var(--sep-colour-271c12))] px-4 py-3 text-[8px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-dfc79c))] transition hover:border-[rgb(var(--sep-colour-a17a45))] hover:bg-[rgb(var(--sep-colour-3b2919))] disabled:cursor-not-allowed disabled:opacity-35"\n              >\n                {isPending\n                  ? "Crafting..."\n                  : "Craft"}\n              </button>\n            </div>\n          </div>\n        </div>\n      </section>\n    </div>\n  );\n}\n'

path.write_text(content, encoding="utf-8")

print("SUCCESS")
print("Crafting layout changed to 25% / 25% / 50%.")
print("Recipes left, ingredients middle, workbench right.")
print("3 ingredients use a triangle; 4 use a diamond.")
print("Existing crafting logic and skin styling preserved.")
print("Next: npm run build")
